    'streakInfoMsg': {'it': 'Completa TUTTE le sessioni della tua scheda ogni microciclo per incrementare il contatore.\n\nSe salti anche solo una sessione in un microciclo, la streak si azzera.\n\nSii costante — ogni microciclo conta!', 'en': 'Complete ALL sessions in your plan every microcycle to increase your streak counter.\n\nMiss even one session in a microcycle and your streak resets to 0.\n\nStay consistent — every microcycle counts!', 'es': 'Completa TODAS las sesiones de tu programa en cada microciclo para aumentar tu contador.\n\nSi te saltas una sesión, tu racha se reinicia a 0.\n\n¡Sé constante — cada microciclo cuenta!', 'pt': 'Complete TODAS as sessões do seu programa a cada microciclo para aumentar seu contador.\n\nPerca uma sessão e sua sequência volta a 0.\n\nSeja constante — cada microciclo conta!', 'fr': 'Complète TOUTES les séances de ton programme à chaque microcycle pour augmenter ton compteur.\n\nRate une séance et ta série repart à 0.\n\nSois régulier — chaque microcycle compte!', 'de': 'Schließe ALLE Einheiten deines Plans in jedem Mikrozyklus ab, um deinen Zähler zu erhöhen.\n\nVerpasse eine Einheit und deine Serie wird auf 0 zurückgesetzt.\n\nBleib konsequent — jeder Mikrozyklus zählt!', 'el': 'Ολοκλήρωσε ΟΛΕΣ τις συνεδρίες του προγράμματός σου σε κάθε μικρόκυκλο για να αυξήσεις τον μετρητή.\n\nΑν χάσεις μια συνεδρία, το σερί μηδενίζεται.\n\nΝα είσαι συνεπής — κάθε μικρόκυκλος μετράει!', 'ar': 'أكمل جميع الجلسات في خطتك في كل دورة صغيرة لزيادة عدادك.\n\nإذا فاتتك جلسة واحدة، تبدأ سلسلتك من الصفر.\n\nكن منتظماً — كل دورة صغيرة تحسب!', 'pl': 'Ukończ WSZYSTKIE sesje w swoim planie w każdym mikrocyklu, aby zwiększyć licznik.\n\nOpuść jedną sesję i twoja seria zaczyna się od nowa.\n\nBądź konsekwentny — każdy mikrocykl ma znaczenie!', 'ro': 'Finalizează TOATE sesiunile din programul tău în fiecare microciclu pentru a crește contorul.\n\nRatezi o sesiune și seria ta se resetează la 0.\n\nFii constant — fiecare microciclu contează!', 'hu': 'Teljesítsd AZ ÖSSZES foglalkozást a tervből minden mikrociklusban a számláló növeléséhez.\n\nHa kihagysz egy foglalkozást, a sorozatod nulláról indul újra.\n\nLegyél következetes — minden mikrociklus számít!'},
    'sessionUnlockedMsg': {'it': 'Sessione sbloccata! {done}/{total} questo microciclo', 'en': 'Session unlocked! {done}/{total} this microcycle', 'es': '¡Sesión desbloqueada! {done}/{total} este microciclo', 'pt': 'Sessão desbloqueada! {done}/{total} neste microciclo', 'fr': 'Séance débloquée ! {done}/{total} ce microcycle', 'de': 'Einheit entsperrt! {done}/{total} in diesem Mikrozyklus', 'el': 'Συνεδρία ξεκλειδώθηκε! {done}/{total} αυτόν τον μικρόκυκλο', 'ar': 'تم فتح الجلسة! {done}/{total} في هذه الدورة الصغيرة', 'pl': 'Sesja odblokowana! {done}/{total} w tym mikrocyklu', 'ro': 'Sesiune deblocată! {done}/{total} în acest microciclu', 'hu': 'Foglalkozás feloldva! {done}/{total} ebben a mikrociklusban'},
    'completeMoreSessions': {'it': 'Completa ancora {n} sessioni per non perdere i tuoi progressi!', 'en': 'Complete {n} more sessions to keep your streak!', 'es': '¡Completa {n} sesiones más para mantener tu racha!', 'pt': 'Complete mais {n} sessões para manter sua sequência!', 'fr': 'Complète encore {n} séances pour garder ta série !', 'de': 'Schließe noch {n} Einheiten ab, um deine Serie zu behalten!', 'el': 'Ολοκλήρωσε ακόμα {n} συνεδρίες για να κρατήσεις το σερί σου!', 'ar': 'أكمل {n} جلسات إضافية للحفاظ على تتابعك!', 'pl': 'Ukończ jeszcze {n} sesji, aby utrzymać swoją serię!', 'ro': 'Finalizează încă {n} sesiuni pentru a-ți păstra seria!', 'hu': 'Teljesíts még {n} foglalkozást a sorozatod megőrzéséhez!'},
    'streakFireMsg': {'it': '{n} micro di fila!', 'en': '{n} microcycles streak!', 'es': '¡{n} microciclos en racha!', 'pt': '{n} microciclos de sequência!', 'fr': '{n} microcycles d\'affilée!', 'de': '{n} Mikrozyklen Strähne!', 'el': '{n} μικρόκυκλοι σερί!', 'ar': '{n} دورات صغيرة متتالية!', 'pl': '{n} mikrocykli z rzędu!', 'ro': '{n} microciclu la rând!', 'hu': '{n} mikrociklus sorozatban!'},
    'streakOnFire': {'it': 'micro di fila!', 'en': 'microcycles on fire!', 'es': '¡microciclos en racha!', 'pt': 'microciclos de seguida!', 'fr': 'microcycles d\'affilée!', 'de': 'Mikrozyklen in Folge!', 'el': 'μικρόκυκλοι σερί!', 'ar': 'دورات صغيرة متتالية!', 'pl': 'mikrocykli z rzędu!', 'ro': 'microciclu la rând!', 'hu': 'mikrociklus egymás után!'},
    'tutorialTitle': {'it': 'Tutorial', 'en': 'Tutorial', 'es': 'Tutorial', 'pt': 'Tutorial', 'fr': 'Tutoriel', 'de': 'Tutorial', 'el': 'Εκμάθηση', 'ar': 'درس تعليمي', 'pl': 'Samouczek', 'ro': 'Tutorial', 'hu': 'Bemutató'},
    'tutorialSubtitle': {'it': 'Il tuo diario di allenamento intelligente', 'en': 'Your smart training journal', 'es': 'Tu diario de entrenamiento inteligente', 'pt': 'Seu diário de treino inteligente', 'fr': 'Ton journal d\'entraînement intelligent', 'de': 'Dein intelligentes Trainingstagbuch', 'el': 'Το έξυπνο ημερολόγιο προπόνησής σου', 'ar': 'يومية تدريبك الذكية', 'pl': 'Twój inteligentny dziennik treningowy', 'ro': 'Jurnalul tău inteligent de antrenament', 'hu': 'Az okos edzésnaplód'},
    'tutorialStep1Title': {'it': 'Esegui la serie', 'en': 'Do the set', 'es': 'Realiza la serie', 'pt': 'Execute a série', 'fr': 'Effectue la série', 'de': 'Führe den Satz aus', 'el': 'Κάνε το σετ', 'ar': 'نفّذ المجموعة', 'pl': 'Wykonaj serię', 'ro': 'Execută setul', 'hu': 'Végezd el a sorozatot'},
    'tutorialStep2Body': {'it': 'Solo dopo aver finito la serie, inserisci i valori e premi Conferma.', 'en': 'Only after finishing the set, enter the values and press Confirm.', 'es': 'Solo después de terminar la serie, ingresa los valores y pulsa Confirmar.', 'pt': 'Somente após terminar a série, insira os valores e pressione Confirmar.', 'fr': 'Seulement après avoir terminé la série, entre les valeurs et appuie sur Confirmer.', 'de': 'Erst nach dem Satz die Werte eingeben und Bestätigen drücken.', 'el': 'Μόνο αφού τελειώσεις το σετ, εισάγαγε τις τιμές και πάτα Επιβεβαίωση.', 'ar': 'بعد الانتهاء من المجموعة فقط، أدخل القيم واضغط تأكيد.', 'pl': 'Dopiero po zakończeniu serii wpisz wartości i naciśnij Potwierdź.', 'ro': 'Numai după terminarea setului, introdu valorile și apasă Confirmă.', 'hu': 'Csak a sorozat befejezése után add meg az értékeket és nyomj Megerősítés-t.'},
    'tutorialStep3Title': {'it': 'Il timer parte da solo', 'en': 'The timer starts automatically', 'es': 'El temporizador inicia solo', 'pt': 'O timer inicia automaticamente', 'fr': 'Le minuteur démarre tout seul', 'de': 'Der Timer startet automatisch', 'el': 'Το χρονόμετρο ξεκινά αυτόματα', 'ar': 'المؤقت يبدأ تلقائياً', 'pl': 'Timer startuje automatycznie', 'ro': 'Timerul pornește automat', 'hu': 'Az időzítő automatikusan indul'},
    'tutorialStep3Body': {'it': 'Il recupero inizia automaticamente. Puoi tenerlo d\'occhio nella barra delle notifiche.', 'en': 'Rest starts automatically. You can follow it in the notification bar.', 'es': 'El descanso comienza automáticamente. Puedes seguirlo en la barra de notificaciones.', 'pt': 'O descanso começa automaticamente. Você pode acompanhar na barra de notificações.', 'fr': 'Le repos démarre automatiquement. Tu peux le suivre dans la barre de notifications.', 'de': 'Die Erholung startet automatisch. Du kannst sie in der Benachrichtigungsleiste verfolgen.', 'el': 'Η ανάπαυση ξεκινά αυτόματα. Μπορείς να την παρακολουθείς στη γραμμή ειδοποιήσεων.', 'ar': 'تبدأ الراحة تلقائياً. يمكنك متابعتها في شريط الإشعارات.', 'pl': 'Odpoczynek zaczyna się automatycznie. Możesz go śledzić w pasku powiadomień.', 'ro': 'Odihna începe automat. O poți urmări în bara de notificări.', 'hu': 'A pihenő automatikusan kezdődik. Az értesítési sávban nyomon követheted.'},
    'tutorialMemoryTitle': {'it': 'L\'app ricorda i tuoi pesi', 'en': 'The app remembers your weights', 'es': 'La app recuerda tus pesos', 'pt': 'O app lembra seus pesos', 'fr': 'L\'app se souvient de tes poids', 'de': 'Die App merkt sich deine Gewichte', 'el': 'Η εφαρμογή θυμάται τα βάρη σου', 'ar': 'التطبيق يتذكر أوزانك', 'pl': 'Aplikacja zapamiętuje twoje ciężary', 'ro': 'Aplicația îți amintește greutățile', 'hu': 'Az alkalmazás megjegyzi a súlyaidat'},
    'tutorialMemoryBody': {'it': 'GymApp suggerisce automaticamente il peso usato l\'ultima volta.', 'en': 'GymApp automatically suggests the weight used last time.', 'es': 'GymApp sugiere automáticamente el peso usado la última vez.', 'pt': 'GymApp sugere automaticamente o peso usado na última vez.', 'fr': 'GymApp suggère automatiquement le poids utilisé la dernière fois.', 'de': 'GymApp schlägt automatisch das zuletzt verwendete Gewicht vor.', 'el': 'Το GymApp προτείνει αυτόματα το βάρος που χρησιμοποιήθηκε την τελευταία φορά.', 'ar': 'يقترح GymApp تلقائياً الوزن المستخدم في آخر مرة.', 'pl': 'GymApp automatycznie sugeruje ciężar użyty ostatnim razem.', 'ro': 'GymApp sugerează automat greutatea folosită ultima dată.', 'hu': 'A GymApp automatikusan javasolja az utoljára használt súlyt.'},
    'tutorialDemoTitle': {'it': 'Fai una prova vera — nessun dato salvato', 'en': 'Try it for real — no data saved', 'es': 'Pruébalo de verdad — sin datos guardados', 'pt': 'Experimente de verdade — sem dados salvos', 'fr': 'Essaie pour de vrai — aucune donnée sauvegardée', 'de': 'Probiere es aus — keine Daten gespeichert', 'el': 'Δοκίμασέ το στην πράξη — χωρίς αποθήκευση δεδομένων', 'ar': 'جربه فعلاً — لا تُحفظ بيانات', 'pl': 'Wypróbuj naprawdę — bez zapisywania danych', 'ro': 'Încearcă cu adevărat — fără date salvate', 'hu': 'Próbáld ki valóban — nem ment adatot'},
    'demoGuideReady': {'it': 'Qui vedi l\'esercizio, le serie da fare e cosa hai fatto l\'ultima volta. Premi il tasto in basso per iniziare.', 'en': 'Here you see the exercise, the sets to do and what you did last time. Tap the button below to start.', 'es': 'Aquí ves el ejercicio, las series que hacer y lo que hiciste la última vez. Pulsa el botón de abajo para empezar.', 'pt': 'Aqui você vê o exercício, as séries a fazer e o que fez da última vez. Toque no botão abaixo para começar.', 'fr': 'Ici tu vois l\'exercice, les séries à faire et ce que tu as fait la dernière fois. Appuie sur le bouton en bas pour commencer.', 'de': 'Hier siehst du die Übung, die Sätze und was du letztes Mal gemacht hast. Tippe unten auf den Button, um zu starten.', 'el': 'Εδώ βλέπεις την άσκηση, τα σετ και τι έκανες την προηγούμενη φορά. Πάτησε το κουμπί κάτω για να ξεκινήσεις.', 'ar': 'هنا ترى التمرين والمجموعات المطلوبة وما فعلته في المرة السابقة. اضغط الزر في الأسفل للبدء.', 'pl': 'Tu widzisz ćwiczenie, serie do wykonania i to, co zrobiłeś ostatnio. Naciśnij przycisk na dole, aby zacząć.', 'ro': 'Aici vezi exercițiul, seriile de făcut și ce ai făcut data trecută. Apasă butonul de jos ca să începi.', 'hu': 'Itt látod a gyakorlatot, a sorozatokat és azt, amit legutóbb csináltál. Nyomd meg a lenti gombot a kezdéshez.'},
    'demoGuideSet': {'it': 'Fai la serie. Poi gira le rotelle su peso e ripetizioni fatte (o tocca il numero per scriverlo) e premi il tasto in basso per registrarla.', 'en': 'Do the set. Then spin the wheels to the weight and reps you did (or tap the number to type it) and press the button below to log it.', 'es': 'Haz la serie. Luego gira las ruedas al peso y las repeticiones hechas (o toca el número para escribirlo) y pulsa el botón de abajo para registrarla.', 'pt': 'Faça a série. Depois gire as rodas até o peso e as repetições feitas (ou toque no número para digitar) e toque no botão abaixo para registrar.', 'fr': 'Fais la série. Puis tourne les molettes sur le poids et les répétitions faites (ou touche le nombre pour l\'écrire) et appuie sur le bouton en bas pour l\'enregistrer.', 'de': 'Mach den Satz. Dann dreh die Räder auf Gewicht und Wiederholungen (oder tippe auf die Zahl, um sie einzugeben) und drück unten auf den Button, um ihn zu speichern.', 'el': 'Κάνε το σετ. Μετά γύρισε τους τροχούς στο βάρος και τις επαναλήψεις που έκανες (ή πάτησε τον αριθμό για να τον γράψεις) και πάτησε το κουμπί κάτω για καταγραφή.', 'ar': 'نفّذ المجموعة. ثم أدر العجلات إلى الوزن والتكرارات التي أنجزتها (أو اضغط على الرقم لكتابته) واضغط الزر في الأسفل لتسجيلها.', 'pl': 'Zrób serię. Potem ustaw pokrętła na ciężar i wykonane powtórzenia (albo dotknij liczby, aby ją wpisać) i naciśnij przycisk na dole, aby ją zapisać.', 'ro': 'Fă seria. Apoi rotește roțile la greutatea și repetările făcute (sau atinge numărul ca să-l scrii) și apasă butonul de jos ca s-o înregistrezi.', 'hu': 'Csináld meg a sorozatot. Utána állítsd a kerekeket a súlyra és az ismétlésekre (vagy koppints a számra a beíráshoz), és nyomd meg a lenti gombot a mentéshez.'},
    'demoGuideRest': {'it': 'Recupero: il timer è partito da solo e ti avvisa alla fine, anche dalle notifiche. Qui vedi il prossimo esercizio; SKIP per ripartire subito.', 'en': 'Rest: the timer started by itself and alerts you at the end, also in the notifications. Here you see the next exercise; SKIP to go again now.', 'es': 'Descanso: el temporizador arrancó solo y te avisa al final, también en las notificaciones. Aquí ves el siguiente ejercicio; SKIP para seguir ya.', 'pt': 'Descanso: o timer começou sozinho e avisa no final, também nas notificações. Aqui você vê o próximo exercício; SKIP para continuar já.', 'fr': 'Récupération : le minuteur est parti tout seul et te prévient à la fin, aussi dans les notifications. Ici tu vois l\'exercice suivant ; SKIP pour repartir tout de suite.', 'de': 'Pause: Der Timer ist von selbst gestartet und meldet sich am Ende, auch in den Benachrichtigungen. Hier siehst du die nächste Übung; SKIP, um sofort weiterzumachen.', 'el': 'Διάλειμμα: το χρονόμετρο ξεκίνησε μόνο του και σε ειδοποιεί στο τέλος, και στις ειδοποιήσεις. Εδώ βλέπεις την επόμενη άσκηση· SKIP για να συνεχίσεις αμέσως.', 'ar': 'الراحة: بدأ المؤقت تلقائيًا وسينبّهك في النهاية، وفي الإشعارات أيضًا. هنا ترى التمرين التالي؛ اضغط SKIP للمتابعة فورًا.', 'pl': 'Przerwa: minutnik ruszył sam i powiadomi cię na końcu, także w powiadomieniach. Tu widzisz następne ćwiczenie; SKIP, aby od razu kontynuować.', 'ro': 'Pauză: cronometrul a pornit singur și te anunță la final, și în notificări. Aici vezi exercițiul următor; SKIP ca să continui imediat.', 'hu': 'Pihenő: az időzítő magától elindult, és a végén szól, az értesítésekben is. Itt látod a következő gyakorlatot; SKIP az azonnali folytatáshoz.'},
    'demoGuideNext': {'it': 'L\'app ricorda pesi e ripetizioni: la prossima volta te li ripropone e ti dice quando aumentare. Con le frecce in alto cambi esercizio. Finisci le serie per vedere il riepilogo.', 'en': 'The app remembers weights and reps: next time it offers them again and tells you when to go up. Use the arrows at the top to switch exercise. Finish the sets to see the recap.', 'es': 'La app recuerda pesos y repeticiones: la próxima vez te los propone y te dice cuándo subir. Con las flechas de arriba cambias de ejercicio. Termina las series para ver el resumen.', 'pt': 'O app lembra pesos e repetições: na próxima vez sugere de novo e diz quando aumentar. Com as setas no topo você troca de exercício. Termine as séries para ver o resumo.', 'fr': 'L\'app retient poids et répétitions : la prochaine fois elle te les repropose et te dit quand augmenter. Avec les flèches en haut tu changes d\'exercice. Termine les séries pour voir le récap.', 'de': 'Die App merkt sich Gewichte und Wiederholungen: Beim nächsten Mal schlägt sie sie wieder vor und sagt dir, wann du steigern sollst. Mit den Pfeilen oben wechselst du die Übung. Beende die Sätze, um die Übersicht zu sehen.', 'el': 'Η εφαρμογή θυμάται βάρη και επαναλήψεις: την επόμενη φορά σου τα ξαναπροτείνει και σου λέει πότε να αυξήσεις. Με τα βέλη πάνω αλλάζεις άσκηση. Τελείωσε τα σετ για να δεις τη σύνοψη.', 'ar': 'يتذكر التطبيق الأوزان والتكرارات: في المرة القادمة يقترحها عليك ويخبرك متى تزيد. استخدم الأسهم في الأعلى لتغيير التمرين. أكمل المجموعات لترى الملخص.', 'pl': 'Aplikacja pamięta ciężary i powtórzenia: następnym razem je zaproponuje i powie, kiedy zwiększyć. Strzałkami u góry zmieniasz ćwiczenie. Dokończ serie, aby zobaczyć podsumowanie.', 'ro': 'Aplicația ține minte greutățile și repetările: data viitoare ți le propune din nou și îți spune când să crești. Cu săgețile de sus schimbi exercițiul. Termină seriile ca să vezi rezumatul.', 'hu': 'Az app megjegyzi a súlyokat és ismétléseket: legközelebb újra felajánlja őket, és szól, mikor emelj. A fenti nyilakkal válthatsz gyakorlatot. Fejezd be a sorozatokat az összegzéshez.'},
    'tutorialStartDemo': {'it': 'Inizia la prova', 'en': 'Start the trial', 'es': 'Iniciar la prueba', 'pt': 'Iniciar o teste', 'fr': 'Lancer l\'essai', 'de': 'Test starten', 'el': 'Ξεκίνα τη δοκιμή', 'ar': 'ابدأ التجربة', 'pl': 'Rozpocznij próbę', 'ro': 'Începe proba', 'hu': 'Próba indítása'},
    'tutorialCompleteTitle': {'it': 'Sei pronto!', 'en': 'You\'re ready!', 'es': '¡Estás listo!', 'pt': 'Você está pronto!', 'fr': 'Tu es prêt !', 'de': 'Du bist bereit!', 'el': 'Είσαι έτοιμος!', 'ar': 'أنت مستعد!', 'pl': 'Jesteś gotowy!', 'ro': 'Ești gata!', 'hu': 'Kész vagy!'},
    'tutorialCompleteBody': {'it': 'Hai completato la prova e conosci già tutte le funzioni essenziali di GymApp. Adesso inizia il tuo vero allenamento!', 'en': 'You completed the trial and already know all the essential features of GymApp. Now start your real workout!', 'es': 'Completaste la prueba y ya conoces todas las funciones esenciales de GymApp. ¡Ahora empieza tu entrenamiento real!', 'pt': 'Você completou o teste e já conhece todas as funcionalidades essenciais do GymApp. Agora comece seu treino real!', 'fr': 'Tu as terminé l\'essai et tu connais déjà toutes les fonctions essentielles de GymApp. Maintenant commence ton vrai entraînement !', 'de': 'Du hast den Test abgeschlossen und kennst bereits alle wesentlichen Funktionen von GymApp. Jetzt starte dein echtes Training!', 'el': 'Ολοκλήρωσες τη δοκιμή και γνωρίζεις ήδη όλες τις βασικές λειτουργίες του GymApp. Τώρα ξεκίνα την πραγματική σου προπόνηση!', 'ar': 'أكملت التجربة وتعرفت بالفعل على جميع الميزات الأساسية لـ GymApp. الآن ابدأ تمرينك الحقيقي!', 'pl': 'Ukończyłeś próbę i znasz już wszystkie podstawowe funkcje GymApp. Teraz zacznij swój prawdziwy trening!', 'ro': 'Ai finalizat proba și cunoști deja toate funcțiile esențiale ale GymApp. Acum începe antrenamentul tău real!', 'hu': 'Befejezted a próbát és már ismered a GymApp összes alapvető funkcióját. Most indítsd el az igazi edzést!'},
    'tryWeightBtn': {'it': 'Ci provo', 'en': 'Let\'s go', 'es': 'Lo intento', 'pt': 'Vou tentar', 'fr': 'J\'essaie', 'de': 'Los geht\'s', 'el': 'Δοκιμάζω', 'ar': 'سأحاول', 'pl': 'Próbuję', 'ro': 'Încerc', 'hu': 'Megpróbálom'},
    'okBtn': {'it': 'Ci provo', 'en': 'Let\'s go', 'es': 'Lo intento', 'pt': 'Vou tentar', 'fr': 'J\'essaie', 'de': 'Los geht\'s', 'el': 'Δοκιμάζω', 'ar': 'سأحاول', 'pl': 'Próbuję', 'ro': 'Încerc', 'hu': 'Megpróbálom'},
